const ATTRS={xmlns:'http://www.w3.org/2000/svg',width:'24',height:'24',viewBox:'0 0 24 24',fill:'none',stroke:'currentColor','stroke-width':'2','stroke-linecap':'round','stroke-linejoin':'round'};
function createIcons(){
document.querySelectorAll('[data-lucide]').forEach(function(el){
const name=el.getAttribute('data-lucide');
const content=icons[name];
if(!content)return;
const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
Object.keys(ATTRS).forEach(function(k){svg.setAttribute(k,ATTRS[k])});
Array.from(el.attributes).forEach(function(a){
if(a.name==='data-lucide')return;
if(a.name==='class'){svg.setAttribute('class','lucide lucide-'+name+' '+a.value)}
else svg.setAttribute(a.name,a.value);
});
svg.innerHTML=content;
el.replaceWith(svg);
});
}
return {createIcons:createIcons};
